/* From Uiverse.io by JkHuger - Tags: loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 180px;
  height: 180px;
  display: flex;
  justify-content: center;
  align-items: center;
  transform-style: preserve-3d;
  transform: perspective(500px) rotateX(45deg);
}

.__UIV_SCOPE__ .loader span {
  position: absolute;
  display: block;
  border: 15px solid #fff;
  box-sizing: border-box;
  border-radius: 50%;
  box-shadow: 0 10px 0 #e0e0e0, inset 0 10px 0 #e0e0e0;
  animation: animate_5013 4.5s ease-in-out infinite;
}

.__UIV_SCOPE__ .loader span:nth-child(1) {
  animation-delay: 0s;
}

.__UIV_SCOPE__ .loader span:nth-child(2) {
  animation-delay: 1.5s;
}

.__UIV_SCOPE__ .loader span:nth-child(3) {
  animation-delay: 3s;
}

@keyframes animate_5013 {
  0% {
    transform: translateZ(-100px);
    width: 100%;
    height: 100%;
  }

  25% {
    transform: translateZ(100px);
    width: 100%;
    height: 100%;
  }

  50% {
    transform: translateZ(100px);
    width: 35%;
    height: 35%;
  }

  75% {
    transform: translateZ(-100px);
    width: 35%;
    height: 35%;
  }

  100% {
    transform: translateZ(-100px);
    width: 100%;
    height: 100%;
  }
}
